    var fn=svmSfxFileOf(item);
    if(!fn){fireNote("Insertion impossible — fichier audio introuvable.");return}
    var tr2=opts&&opts.track&&SVM_TRACK_BUS[opts.track]?opts.track:svmSfxTrackOf(item&&item.kind);
