    var q3=on.eq3||{bass_db:0,mid_db:0,treble_db:0};
    ramp(P.bass.gain,q3.bass_db);ramp(P.mid.gain,q3.mid_db);ramp(P.treb.gain,q3.treble_db);
    var c=on.compressor;
