    var el=mr.current&&mr.current.parentElement;
    if(!el)return;
    var read=function(){
      var w=el.clientWidth||0,h=el.clientHeight||0;
      setFr(function(p){return p.w===w&&p.h===h?p:{w:w,h:h}})};
    read();
